package guidancecontent

import (
	"github.com/jaxxstorm/fed/internal/readiness"
	"io/fs"
)

// IAM builds all 18 identity and access variants without asserting implementation.
func IAM(rules, markdown fs.FS) (readiness.Package, error) {
	return technicalDraft(rules, markdown, "IAM", "identity-and-access-management", 18, []technicalRecipe{
		{code: "AAM", statement: "The lifecycle and privileges of all accounts, roles, and groups are securely managed using automation.",
			purpose: "Demonstrate secure automated lifecycle and privilege management for the complete account, role and group population, including local and non-user identities.", capability: "identity-population-and-authority",
			scope:   "All accounts, roles and groups across identity providers, local applications, cloud accounts and workload identities supporting the service; include privileged, emergency and inactive identities.",
			setup:   "Locate identity authorities, account/role/group exports and lifecycle/privilege automation definitions. Reconcile federated and local populations and identify automation owners.",
			records: "Identity population reconciliations, lifecycle workflow revisions, permission automation policies, provisioning/change/disablement execution records, failures and exception coverage.",
			review:  "Trace creation, changes and retirement through actual automation and privilege decisions. Evaluate security of workflow authorization and failures; do not equate directory synchronization with complete secure lifecycle management.", insufficient: "An identity-provider subscription or provisioning demonstration that omits roles, groups, privilege changes or termination.",
			facets: []technicalFacet{{"lifecycle", "Automation securely manages identity lifecycle transitions.", "Provisioning, modification and retirement runs tied to source identities and authorized workflow versions.", "Manual onboarding tickets alone."}, {"privileges of all accounts, roles, and groups", "Automated privilege management covers accounts, roles and groups.", "Privilege assignments, group membership/role changes, automation runs and full-population reconciliation.", "Account creation automation with unexamined static administrator groups."}}},
		{code: "APM", statement: "Secure passwordless methods are used for user authentication and authorization when feasible, otherwise strong passwords with phishing-resistant MFA is used.",
			purpose: "Evaluate actual user access paths and the feasibility branch: secure passwordless authentication and authorization where feasible, otherwise strong passwords together with phishing-resistant MFA.", capability: "identity-population-and-authority",
			scope:   "User authentication and authorization paths, including federated, local, administrative, recovery and emergency access; distinguish non-user identities assessed under SNU.",
			setup:   "Locate authentication/authorization path inventory, passwordless configurations, feasibility decisions and fallback password/MFA policy with observed sign-in records.",
			records: "Path-specific feasibility rationale, passwordless method and authorization configuration, authentication observations, fallback strong-password policy and phishing-resistant MFA enforcement evidence.",
			review:  "For every path, establish feasibility and verify the selected branch in actual operation. Check recovery and bypass paths and phishing resistance of fallback factors; generic MFA enrollment is insufficient. Do not collect passwords or private authenticators.", insufficient: "An MFA-enabled flag, SMS/OTP-only fallback, or a passwordless roadmap without feasibility and operating evidence.",
			facets: []technicalFacet{{"Secure passwordless methods are used for user authentication and authorization when feasible", "Feasible user paths use secure passwordless methods for authentication and authorization.", "Feasibility decisions, method configuration, authorization path mapping and attributed sign-in observations.", "One administrator's passwordless enrollment generalized to all users."}, {"otherwise strong passwords with phishing-resistant MFA is used", "Infeasible passwordless paths use both strong passwords and phishing-resistant MFA.", "Infeasibility rationale, password requirements, phishing-resistant factor enforcement and fallback/bypass observations.", "Strong passwords alone or generic MFA without phishing resistance."}}},
		{code: "ELP", statement: "Identity and access management measures are used and persistently reviewed to ensure each user or device can only access the resources they need.",
			purpose: "Compare effective user and device access to justified resource needs and show repeated review of those measures; assigned role names do not establish least privilege.", capability: "identity-population-and-authority",
			scope:   "Each user and device and its effective resource permissions, including inherited memberships, federation, device identities and cross-account access.",
			setup:   "Locate user/device population, resource-need authorizations, effective permission exports and access-review history.",
			records: "User/device-to-resource-need mappings, effective entitlement calculations or observations, dated access reviews, decisions and unresolved exceptions.",
			review:  "Reconcile effective permissions with justified needs for both users and devices. Inspect inherited and indirect access and review conclusions over time; record unsupported need or missing visibility separately.", insufficient: "Role names, a user-only certification exercise or access-review completion counts without resource-need comparisons."},
		{code: "JIT", statement: "A least-privileged, role and attribute-based, and just-in-time security authorization model is used and persistently reviewed for all user and non-user accounts and services.",
			purpose: "Evaluate the combined authorization model: least privilege, roles, attributes and just-in-time authorization for human and workload identities, with repeated review.", capability: "identity-population-and-authority",
			scope:   "All user and non-user accounts and services; include workload-to-workload and administrative paths, not only interactive elevation.",
			setup:   "Locate authorization policies, role/attribute authorities, time-bounded grant mechanisms and review records across user and non-user populations.",
			records: "Role and attribute policy versions, justified minimum privileges, request/grant/expiry or revocation records, service identity coverage and dated model reviews.",
			review:  "Trace representative authorization decisions through roles, attributes, least-privilege scope and just-in-time grant lifetime; reconcile all identity categories and review history. A periodic password rotation does not establish JIT authorization.", insufficient: "Interactive administrator elevation alone, or RBAC without attribute and just-in-time behavior.",
			facets: []technicalFacet{{"least-privileged, role and attribute-based", "Authorization decisions combine least privilege with roles and attributes.", "Effective decisions tied to role/attribute inputs and justified resource needs.", "A role catalog without attribute evaluation."}, {"just-in-time", "Authorization is granted just in time, with bounded useful lifetime.", "Grant request, activation, expiration/revocation observations and standing-access exceptions.", "Permanent privilege plus periodic access review."}, {"all user and non-user accounts and services", "The model and its persistent review cover human and non-human identities and services.", "Identity-class denominator, policy coverage and review history for workload and user paths.", "A human administrator-only sample."}}},
		{code: "SNU", statement: "Appropriately secure authentication methods are used and persistently reviewed for non-user accounts and services.",
			purpose: "Evaluate secure authentication of service and other non-human identities using risk-appropriate methods and repeated review; do not impose human MFA on machine authentication.", capability: "identity-population-and-authority",
			scope:   "Non-user accounts, service principals, workload identities, integrations and service-to-service authentication paths.",
			setup:   "Locate workload identity inventory, authentication method configurations, trust relationships and method-security reviews.",
			records: "Non-user identity/method mapping, trust and credential-lifetime settings, authentication observations, risk-appropriateness rationale and repeated review conclusions; use secret metadata rather than secret values.",
			review:  "Assess each method's appropriateness in its trust context and verify actual authentication and repeated review. Distinguish credential storage from authentication security and identify unreviewed service identities.", insufficient: "A vault inventory or rotation schedule alone without authentication-path review."},
		{code: "SUS", statement: "Accounts with privileged access are disabled or otherwise secured in response to suspicious activity.",
			purpose: "Trace suspicious activity involving privileged accounts to disablement or other demonstrated securing actions; neither an alert nor a closed ticket proves the account was secured.", capability: "privileged-activity-response",
			scope:   "Accounts with privileged access and suspicious-activity cases involving them, including human, emergency and non-user privileged identities.",
			setup:   "Locate privileged account inventory, suspicious-activity detection/case sources and account-state response history, with identity correlation across systems.",
			records: "Suspicious-event identifiers and times, privileged identity correlation, response decisions, disablement or alternative securing records and resulting access-state observations.",
			review:  "Follow cases to changed account security state and explain how an alternative to disablement secured the account. Reconcile the case population; an absence of accessible cases is not evidence of no suspicious activity. Inspect existing records without disabling accounts.", insufficient: "An alert, triage acknowledgment or ticket closure with no evidence of disablement or other securing action.",
			timing: "When suspicious activity affects an account with privileged access, retain event, decision and securing-action timestamps. This statement gives no numeric response deadline. A supported no-event period limits the operating claim; exercises can demonstrate capability but not an actual response."},
	})
}
